CREATE TABLE public.user_blocks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), blocker_id uuid NOT NULL DEFAULT auth.uid(), blocked_user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(blocker_id,blocked_user_id), CHECK(blocker_id<>blocked_user_id));
GRANT SELECT,INSERT,DELETE ON public.user_blocks TO authenticated;
GRANT ALL ON public.user_blocks TO service_role;
ALTER TABLE public.user_blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_blocks ON public.user_blocks TO authenticated USING(blocker_id=auth.uid()) WITH CHECK(blocker_id=auth.uid());
CREATE TABLE public.user_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id uuid NOT NULL DEFAULT auth.uid(),reported_user_id uuid NOT NULL,content_type text NOT NULL,content_id uuid NOT NULL,reason text NOT NULL CHECK(reason IN ('harassment','inappropriate','spam','other')),details text NOT NULL DEFAULT '' CHECK(length(details)<=1000),content_preview text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','dismissed','removed')),created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,reviewed_by uuid,CHECK(content_type IN ('profile','event_comment','group_message','event_photo','event','group','feedback','feedback_comment','bucket_item','what_option')));
GRANT SELECT,INSERT ON public.user_reports TO authenticated;
GRANT ALL ON public.user_reports TO service_role;
ALTER TABLE public.user_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_reports ON public.user_reports FOR SELECT TO authenticated USING(reporter_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY submit_reports ON public.user_reports FOR INSERT TO authenticated WITH CHECK(reporter_id=auth.uid() AND status='open' AND reviewed_by IS NULL AND reviewed_at IS NULL);
CREATE TABLE public.moderation_hidden (content_type text NOT NULL,content_id uuid NOT NULL,hidden_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(content_type,content_id));
GRANT SELECT ON public.moderation_hidden TO authenticated;
GRANT ALL ON public.moderation_hidden TO service_role;
ALTER TABLE public.moderation_hidden ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_hidden_read ON public.moderation_hidden FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.content_visible(_type text,_id uuid,_author uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.user_blocks b WHERE b.blocker_id=auth.uid() AND b.blocked_user_id=_author) AND NOT EXISTS(SELECT 1 FROM public.moderation_hidden h WHERE h.content_type=_type AND h.content_id=_id) AND NOT EXISTS(SELECT 1 FROM public.user_reports r WHERE r.reporter_id=auth.uid() AND r.content_type=_type AND r.content_id=_id AND r.status='open'); $$;
REVOKE ALL ON FUNCTION public.content_visible(text,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.content_visible(text,uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.validate_user_report() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE owner_id uuid; preview text; BEGIN CASE NEW.content_type
WHEN 'profile' THEN SELECT user_id,username || E'\n' || coalesce(bio,'') INTO owner_id,preview FROM public.profiles WHERE user_id=NEW.content_id;
WHEN 'event_comment' THEN SELECT user_id,content INTO owner_id,preview FROM public.event_comments WHERE id=NEW.content_id;
WHEN 'group_message' THEN SELECT user_id,content INTO owner_id,preview FROM public.group_messages WHERE id=NEW.content_id;
WHEN 'event_photo' THEN SELECT user_id,storage_path INTO owner_id,preview FROM public.event_photos WHERE id=NEW.content_id;
WHEN 'event' THEN SELECT created_by,title || E'\n' || coalesce(notes,'') INTO owner_id,preview FROM public.events WHERE id=NEW.content_id;
WHEN 'group' THEN SELECT created_by,name || E'\n' || coalesce(description,'') INTO owner_id,preview FROM public.groups WHERE id=NEW.content_id;
WHEN 'feedback' THEN SELECT user_id,title || E'\n' || coalesce(description,'') INTO owner_id,preview FROM public.feedback WHERE id=NEW.content_id;
WHEN 'feedback_comment' THEN SELECT user_id,content INTO owner_id,preview FROM public.feedback_comments WHERE id=NEW.content_id;
WHEN 'bucket_item' THEN SELECT added_by,title || E'\n' || coalesce(description,'') INTO owner_id,preview FROM public.bucket_list_items WHERE id=NEW.content_id;
WHEN 'what_option' THEN SELECT suggested_by,title INTO owner_id,preview FROM public.event_what_options WHERE id=NEW.content_id;
ELSE RAISE EXCEPTION 'Invalid content type'; END CASE;
IF owner_id IS NULL OR owner_id=auth.uid() OR owner_id<>NEW.reported_user_id THEN RAISE EXCEPTION 'Content unavailable for reporting'; END IF;
NEW.content_preview=left(coalesce(preview,''),2000); RETURN NEW; END; $$;
CREATE TRIGGER validate_report BEFORE INSERT ON public.user_reports FOR EACH ROW EXECUTE FUNCTION public.validate_user_report();
CREATE OR REPLACE FUNCTION public.review_user_report(_report_id uuid,_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE report public.user_reports; BEGIN
IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF;
IF _action NOT IN ('dismissed','removed') THEN RAISE EXCEPTION 'Invalid action'; END IF;
SELECT * INTO report FROM public.user_reports WHERE id=_report_id FOR UPDATE;
IF report.id IS NULL THEN RAISE EXCEPTION 'Report not found'; END IF;
IF _action='removed' THEN INSERT INTO public.moderation_hidden(content_type,content_id,hidden_by) VALUES(report.content_type,report.content_id,auth.uid()) ON CONFLICT DO NOTHING; END IF;
UPDATE public.user_reports SET status=_action,reviewed_at=now(),reviewed_by=auth.uid() WHERE id=_report_id; END; $$;
REVOKE ALL ON FUNCTION public.review_user_report(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.review_user_report(uuid,text) TO authenticated;
CREATE POLICY safety_visibility ON public.profiles AS RESTRICTIVE FOR SELECT TO authenticated USING(public.content_visible('profile',user_id,user_id));
CREATE POLICY safety_visibility ON public.events AS RESTRICTIVE FOR SELECT TO authenticated USING(public.content_visible('event',id,created_by));
CREATE POLICY safety_visibility ON public.groups AS RESTRICTIVE FOR SELECT TO authenticated USING(public.content_visible('group',id,created_by));
CREATE POLICY safety_visibility ON public.event_comments AS RESTRICTIVE FOR SELECT TO authenticated USING(public.content_visible('event_comment',id,user_id));
CREATE POLICY safety_visibility ON public.group_messages AS RESTRICTIVE FOR SELECT TO authenticated USING(public.content_visible('group_message',id,user_id));
CREATE POLICY safety_visibility ON public.event_photos AS RESTRICTIVE FOR SELECT TO authenticated USING(public.content_visible('event_photo',id,user_id));
CREATE POLICY safety_visibility ON public.feedback AS RESTRICTIVE FOR SELECT TO authenticated USING(public.content_visible('feedback',id,user_id));
CREATE POLICY safety_visibility ON public.feedback_comments AS RESTRICTIVE FOR SELECT TO authenticated USING(public.content_visible('feedback_comment',id,user_id));
CREATE POLICY safety_visibility ON public.bucket_list_items AS RESTRICTIVE FOR SELECT TO authenticated USING(public.content_visible('bucket_item',id,added_by));
CREATE POLICY safety_visibility ON public.event_what_options AS RESTRICTIVE FOR SELECT TO authenticated USING(public.content_visible('what_option',id,suggested_by));
CREATE POLICY safety_activity ON public.activity_feed AS RESTRICTIVE FOR SELECT TO authenticated USING(source_user_id IS NULL OR public.content_visible('profile',source_user_id,source_user_id));